<?php require_once dirname(__DIR__, 2).'/includes/config.php';$p=db();$type=$_GET['type']??'excel';$year=(int)($_GET['year']??0);$q="SELECT au.audit_date,a.area_name,au.auditor,au.period,c.item_no,c.category,c.max_score,s.score1,s.score2,s.score3,s.note FROM scores s JOIN audits au ON au.id=s.audit_id JOIN areas a ON a.id=au.area_id JOIN criteria c ON c.id=s.criterion_id";if($year)$q.=" WHERE SUBSTR(au.audit_date,1,4)=". $p->quote(sprintf('%04d',$year));$q.=" ORDER BY au.audit_date DESC,a.area_name,c.item_no";$rows=$p->query($q)->fetchAll();if($type==='csv'){header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="5S_scores.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,['วันที่','พื้นที่','ผู้ตรวจ','รอบ/กะ','ข้อ','หมวด','เต็ม','ผู้1','ผู้2','ผู้3','เฉลี่ย','%','หมายเหตุ']);foreach($rows as $r){$av=score_avg($r['score1'],$r['score2'],$r['score3']);fputcsv($o,[$r['audit_date'],$r['area_name'],$r['auditor'],$r['period'],$r['item_no'],$r['category'],$r['max_score'],$r['score1'],$r['score2'],$r['score3'],$av,$av===null?'':percent($av,$r['max_score']),$r['note']]);}exit;}header('Content-Type:application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition:attachment; filename="5S_scores.xls"');echo '<html><meta charset="utf-8"><base href="<?=htmlspecialchars(FIVE_S_BASE,ENT_QUOTES)?>"><table border="1"><tr><th>วันที่</th><th>พื้นที่</th><th>ผู้ตรวจ</th><th>รอบ/กะ</th><th>ข้อ</th><th>หมวด</th><th>เต็ม</th><th>ผู้1</th><th>ผู้2</th><th>ผู้3</th><th>เฉลี่ย</th><th>%</th><th>หมายเหตุ</th></tr>';foreach($rows as $r){$av=score_avg($r['score1'],$r['score2'],$r['score3']);echo '<tr>';foreach([$r['audit_date'],$r['area_name'],$r['auditor'],$r['period'],$r['item_no'],$r['category'],$r['max_score'],$r['score1'],$r['score2'],$r['score3'],$av,$av===null?'':percent($av,$r['max_score']),$r['note']] as $v)echo '<td>'.h($v).'</td>';echo '</tr>';}echo '</table></html>';exit;